import game from "@/data/game.json";
import type { Icon, Item, Monster, Role, World } from "./types";

/**
 * Static game data bundled into the site (generated by `npm run web:data` at the repo root).
 * The site is fully static — no API calls.
 */
export const GAME = game as unknown as { world: World; icons: Icon[]; roles: Role[]; items: Item[]; bestiary: Monster[] };

/** Hook-style accessor (data is static, error is always null). */
export function useGame<K extends keyof typeof GAME>(key: K): { data: (typeof GAME)[K]; error: string | null } {
  return { data: GAME[key], error: null };
}
